(1844153, 253575, 5728, '<td valign="top">Good one Manny, kind of a different direction for you isn''t it? Good to see you broadening out a bit now, I like it :)</td>', 'Good one Manny, kind of a different direction for you isn''t it? Good to see you broadening out a bit now, I like it :)', '2005-11-07 07:02:25.000000', NULL, 1),
(1844155, 253499, 5728, '<td valign="top">Brilliant, and impressive how you trained those guys to do that for you :)</td>', 'Brilliant, and impressive how you trained those guys to do that for you :)', '2005-11-07 07:04:33.000000', NULL, 1),
(1844156, 253775, 5728, '<td valign="top">How bizarre...</td>', 'How bizarre...', '2005-11-07 07:04:54.000000', NULL, 1),
(1844157, 252619, 5728, '<td valign="top">Spooky looking cat :) Good shot.</td>', 'Spooky looking cat :) Good shot.', '2005-11-07 07:05:55.000000', NULL, 1),
(1844158, 254480, 5728, '<td valign="top">Choice, I like the result here. Maybe I would have turned him just slightly more away so that the far cheek doesn''t come into the frame. It looks a little out of place somehow, but still one of the best shots here!</td>', 'Choice, I like the result here. Maybe I would have turned him just slightly more away so that the far cheek doesn''t come into the frame. It looks a little out of place somehow, but still one of the best shots here!', '2005-11-07 07:07:29.000000', NULL, 1),
(1844159, 254482, 5728, '<td valign="top">Snap shot.... at least you could have gotten rid of the red eyes.</td>', 'Snap shot.... at least you could have gotten rid of the red eyes.', '2005-11-07 07:08:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1844165, 254518, 29797, '<td valign="top">Another great example of the creative mind of SCalvert? (please excuse me if I''m wrong.) This is GREAT, and an excellent take on the challenge!!! Composition, lighting are all superb, and the fall leaves are a nice touch. Well done!</td>', 'Another great example of the creative mind of SCalvert? (please excuse me if I''m wrong.) This is GREAT, and an excellent take on the challenge!!! Composition, lighting are all superb, and the fall leaves are a nice touch. Well done!', '2005-11-07 07:25:29.000000', NULL, 1),
(1844185, 253075, 24454, '<td valign="top">What a find for a perfect photo for this challenge.    I love the feel of this.  Love it!</td>', 'What a find for a perfect photo for this challenge.    I love the feel of this.  Love it!', '2005-11-07 07:47:23.000000', NULL, 1),
(1844188, 254368, 44860, '<td valign="top">Impressive setup...9</td>', 'Impressive setup...9', '2005-11-07 07:48:48.000000', NULL, 1),
(1844198, 254368, 26464, '<td valign="top">hmm.. should i be sending this pic to the cops? lol<br/></td>', 'hmm.. should i be sending this pic to the cops? lol', '2005-11-07 07:58:46.000000', NULL, 1),
(1844252, 254481, 15711, '<td valign="top">I love the guy''s expression.  He seems thoroughly ticked off. The spray paint sure is nice and tidy for "graffiti" but no fautl for that.  His placement in the shot is perfect to showcase the words. Love the old brick building as the backdrop.  If indeed you found this and didn''t spray paint it yourself - WOW 9</td>', 'I love the guy''s expression.  He seems thoroughly ticked off. The spray paint sure is nice and tidy for "graffiti" but no fautl for that.  His placement in the shot is perfect to showcase the words. Love the old brick building as the backdrop.  If indeed you found this and didn''t spray paint it yourself - WOW 9', '2005-11-07 08:35:17.000000', NULL, 1),
(1844255, 252727, 15711, '<td valign="top">This is exceptionally artful. I love how he blends into the leaves as if he''s sinking in a dreamlike state. The fall leaves are the perfect palette!  Beautiful and well executed. 9</td>', 'This is exceptionally artful. I love how he blends into the leaves as if he''s sinking in a dreamlike state. The fall leaves are the perfect palette!  Beautiful and well executed. 9', '2005-11-07 08:36:02.000000', NULL, 1),
(1844256, 254253, 15711, '<td valign="top">Great grungy feel to it although the colors are pleaseant tnd vivid. Great leading line to the person on the floor. Nicely done. 9</td>', 'Great grungy feel to it although the colors are pleaseant tnd vivid. Great leading line to the person on the floor. Nicely done. 9', '2005-11-07 08:36:44.000000', NULL, 1),
(1844257, 254205, 15711, '<td valign="top">This is a bit contrived, but I really really like it. The BYE really makes the photo. It is simple and tack sharp.  The "blood" even has light sparkling off of it. WOW 9</td>', 'This is a bit contrived, but I really really like it. The BYE really makes the photo. It is simple and tack sharp.  The "blood" even has light sparkling off of it. WOW 9', '2005-11-07 08:37:19.000000', NULL, 1),
(1844258, 254540, 15711, '<td valign="top">I couldn''t imagine a more nostalgic photo than an old truck, ocvered in weeds and vines done in an antique filter.  The lighting is spot on and I love the textural variations between the old post, the leaves and brush and the truck.  AWESOME 9</td>', 'I couldn''t imagine a more nostalgic photo than an old truck, ocvered in weeds and vines done in an antique filter.  The lighting is spot on and I love the textural variations between the old post, the leaves and brush and the truck.  AWESOME 9', '2005-11-07 08:38:20.000000', NULL, 1),
(1844260, 254518, 15711, '<td valign="top">ROFL  This is pretty darn funny. The shininess of the yellow brick road seems a bit plastic and fake. Maybe if you did a slight desat and maybe did some dodge and burn to it.  Just a thought.  I still like it and love the old building''s peeling paint along with the strewn sycamore (? ) leaves. Fun and entertaining.</td>', 'ROFL  This is pretty darn funny. The shininess of the yellow brick road seems a bit plastic and fake. Maybe if you did a slight desat and maybe did some dodge and burn to it.  Just a thought.  I still like it and love the old building''s peeling paint along with the strewn sycamore (? ) leaves. Fun and entertaining.', '2005-11-07 08:40:03.000000', NULL, 1),
(1844262, 254312, 15711, '<td valign="top">Wow - the foxhounds with the beautiful white steed and his red coated rider- WOW. I love the gray sky too. Poor fox.</td>', 'Wow - the foxhounds with the beautiful white steed and his red coated rider- WOW. I love the gray sky too. Poor fox.', '2005-11-07 08:41:02.000000', NULL, 1),
(1844264, 254060, 15711, '<td valign="top">I think my favorite fall scene of this challenge. Rich dark colors and the perfect leading line. I don''t even mind that it''s dead centered.  Makes me want to kick leaves as I walk down the path. 8</td>', 'I think my favorite fall scene of this challenge. Rich dark colors and the perfect leading line. I don''t even mind that it''s dead centered.  Makes me want to kick leaves as I walk down the path. 8', '2005-11-07 08:42:00.000000', NULL, 1),
(1844267, 254068, 33379, '<td valign="top">omg WOW! i love this image, one of my faves!</td>', 'omg WOW! i love this image, one of my faves!', '2005-11-07 08:42:19.000000', NULL, 1),
(1844270, 253625, 15711, '<td valign="top">Great depiction of loneliness and dispair. I like the upturned toes with the light on them.  In fact the lighting for the whole shot is good and spotlights that poor guy in the corner. 8</td>', 'Great depiction of loneliness and dispair. I like the upturned toes with the light on them.  In fact the lighting for the whole shot is good and spotlights that poor guy in the corner. 8', '2005-11-07 08:45:10.000000', NULL, 1),
(1844273, 253575, 15711, '<td valign="top">The "blood" seems a tad overdone on her face.  Her expression is emotive and desperate. The whole idea is pretty clever. 8</td>', 'The "blood" seems a tad overdone on her face.  Her expression is emotive and desperate. The whole idea is pretty clever. 8', '2005-11-07 08:46:02.000000', NULL, 1),
(1844274, 252884, 15711, '<td valign="top">This is tack sharp and really clever.  I like it alot with the white background to showcase the green and brown tones of the bug and the stem. 8</td>', 'This is tack sharp and really clever.  I like it alot with the white background to showcase the green and brown tones of the bug and the stem. 8', '2005-11-07 08:46:33.000000', NULL, 1),
(1844275, 253782, 33379, '<td valign="top">is this roadrunner? looks like the same girl in all your images. great actress!</td>', 'is this roadrunner? looks like the same girl in all your images. great actress!', '2005-11-07 08:46:41.000000', NULL, 1),
(1844276, 254354, 15711, '<td valign="top">ROFL  That is one pissed off kitty!!!!! I like the screen as the source of texture.  Great expression!! 8</td>', 'ROFL  That is one pissed off kitty!!!!! I like the screen as the source of texture.  Great expression!! 8', '2005-11-07 08:47:11.000000', NULL, 1),
(1844279, 254022, 15711, '<td valign="top">Nice foggy shot. I like that there is almost no color, yet it isn''t black and white. The wave hitting with the spray in the foreground is a nice exclamation mark for this shot. The leading line is nice too. 8</td>', 'Nice foggy shot. I like that there is almost no color, yet it isn''t black and white. The wave hitting with the spray in the foreground is a nice exclamation mark for this shot. The leading line is nice too. 8', '2005-11-07 08:48:01.000000', NULL, 1),
(1844280, 253930, 15711, '<td valign="top">This is so simple and almost boring, but I love it.  The filtratioan really makes it extraordinary. The brown and gray tones are so wintery and lonely feeling.  I like it ALOT!! 8</td>', 'This is so simple and almost boring, but I love it.  The filtratioan really makes it extraordinary. The brown and gray tones are so wintery and lonely feeling.  I like it ALOT!! 8', '2005-11-07 08:48:48.000000', NULL, 1),
(1844281, 254315, 15711, '<td valign="top">If this didn''t have a great title, I probably would score it a tad lower. It explains it without it going on and on. I like the blurred figure at the top and the focused metal railings.  Nicely done.</td>', 'If this didn''t have a great title, I probably would score it a tad lower. It explains it without it going on and on. I like the blurred figure at the top and the focused metal railings.  Nicely done.', '2005-11-07 08:49:32.000000', NULL, 1),
(1844369, 253964, 29658, '<td valign="top">What I like: the scene. What I don''t like: The composition is too central. ;-)</td>', 'What I like: the scene. What I don''t like: The composition is too central. ;-)', '2005-11-07 09:37:41.000000', NULL, 1),
(1844379, 254042, 29658, '<td valign="top">Great moment. A closer look, without cables would have been great.</td>', 'Great moment. A closer look, without cables would have been great.', '2005-11-07 09:46:06.000000', NULL, 1),
(1844412, 252619, 35545, '<td valign="top">This is a great animal shot, but to me, you''re using the title to pull it into the challenge.</td>', 'This is a great animal shot, but to me, you''re using the title to pull it into the challenge.', '2005-11-07 10:01:39.000000', NULL, 1),
(1844414, 254393, 35545, '<td valign="top">The blurred trees in the background really bother me.  It looks as if the camera shook -- not the usual DOF.</td>', 'The blurred trees in the background really bother me.  It looks as if the camera shook -- not the usual DOF.', '2005-11-07 10:03:17.000000', NULL, 1),
(1844416, 251671, 35545, '<td valign="top">II wish this were bigger.  I''d also get rid of the heavy black border.</td>', 'II wish this were bigger.  I''d also get rid of the heavy black border.', '2005-11-07 10:03:47.000000', NULL, 1),
(1844418, 253782, 35545, '<td valign="top">This looks too contrived.  It might have been better without the man at the left.</td>', 'This looks too contrived.  It might have been better without the man at the left.', '2005-11-07 10:04:45.000000', NULL, 1),
(1844421, 254352, 35545, '<td valign="top">Sorry, but this just  looks too over-processed and blurry.  Also, I don''t get much sense of the path ending.  It looks like it keeps on going, right into that dark patch.</td>', 'Sorry, but this just  looks too over-processed and blurry.  Also, I don''t get much sense of the path ending.  It looks like it keeps on going, right into that dark patch.', '2005-11-07 10:07:34.000000', NULL, 1),
(1844423, 253902, 35545, '<td valign="top">Nice picture and concept.  Check your spelling, though.</td>', 'Nice picture and concept.  Check your spelling, though.', '2005-11-07 10:08:10.000000', NULL, 1),
(1844425, 254122, 29658, '<td valign="top">If you darken the sky I think that the picture will improve a lot.</td>', 'If you darken the sky I think that the picture will improve a lot.', '2005-11-07 10:09:39.000000', NULL, 1),
(1844428, 253708, 35545, '<td valign="top">The diagonal orientation doesn''t do much for me in this case.  Colors look washed out.  I really like the sign.  I think this would have been better with some work on the color.</td>', 'The diagonal orientation doesn''t do much for me in this case.  Colors look washed out.  I really like the sign.  I think this would have been better with some work on the color.', '2005-11-07 10:10:39.000000', NULL, 1),
(1844431, 254518, 1570, '<td valign="top">outstanding!</td>', 'outstanding!', '2005-11-07 10:11:25.000000', NULL, 1),
(1844432, 253964, 35545, '<td valign="top">Please, get rid of that border.</td>', 'Please, get rid of that border.', '2005-11-07 10:11:38.000000', NULL, 1),
(1844435, 254417, 35545, '<td valign="top">I think this could have been cropped tighter IMHO the additional foliage at the top doesn''t add that much and you would come closer to the Rule of Thirds.</td>', 'I think this could have been cropped tighter IMHO the additional foliage at the top doesn''t add that much and you would come closer to the Rule of Thirds.', '2005-11-07 10:13:06.000000', NULL, 1),
(1844464, 253650, 35804, '<td valign="top">I really like the selective desat. here...very nice.</td>', 'I really like the selective desat. here...very nice.', '2005-11-07 10:25:45.000000', NULL, 1),
(1844468, 254562, 35804, '<td valign="top">Now if we saw the tail end of a roach sticking out of that trap...that would be perfect!  : }</td>', 'Now if we saw the tail end of a roach sticking out of that trap...that would be perfect!  : }', '2005-11-07 10:27:28.000000', NULL, 1),
(1844474, 254206, 35804, '<td valign="top">I find this funny...does that mean I need to be commited? Oh...and the light on that rope is perfect.  ; }</td>', 'I find this funny...does that mean I need to be commited? Oh...and the light on that rope is perfect.  ; }', '2005-11-07 10:28:57.000000', NULL, 1),
(1844478, 252884, 40977, '<td valign="top">An amazing shot.  Sharp Focus and brilliant details --10--</td>', 'An amazing shot.  Sharp Focus and brilliant details --10--', '2005-11-07 10:33:14.000000', NULL, 1),
(1844481, 254499, 40977, '<td valign="top">Wonderful take on the challenge. Great angle and overall feel. --9--</td>', 'Wonderful take on the challenge. Great angle and overall feel. --9--', '2005-11-07 10:33:59.000000', NULL, 1),
(1844484, 254073, 40977, '<td valign="top">Simply Amazing.  Love the sharp focus and the detail you were able to show. I don''t think you could have titled this image better.  I don''t think anyone could have done this shot better than your capture/edit here -- well done --10--</td>', 'Simply Amazing.  Love the sharp focus and the detail you were able to show. I don''t think you could have titled this image better.  I don''t think anyone could have done this shot better than your capture/edit here -- well done --10--', '2005-11-07 10:35:40.000000', NULL, 1),
(1844487, 253575, 40977, '<td valign="top">One of my favorites in this competition.  Evokes feeling - I love the composition of the image the best.  The grundgy color adds to the overall feel --well done--10</td>', 'One of my favorites in this competition.  Evokes feeling - I love the composition of the image the best.  The grundgy color adds to the overall feel --well done--10', '2005-11-07 10:37:17.000000', NULL, 1),
(1844491, 254022, 40977, '<td valign="top">Great Shot....A really wonderful scene that is soft and lovely....you brought so much together in this image.  Well done --8--</td>', 'Great Shot....A really wonderful scene that is soft and lovely....you brought so much together in this image.  Well done --8--', '2005-11-07 10:40:00.000000', NULL, 1),
(1844502, 254122, 35804, '<td valign="top">A nice story you have created here...very well done.</td>', 'A nice story you have created here...very well done.', '2005-11-07 10:47:20.000000', NULL, 1),
(1844507, 254312, 35804, '<td valign="top">Such elegance...that horse is gorgeous...I must admit I don''t like the idea of the fox hunt but I never seem to tire of looking at pictures of the scenes, I think it''s the whole "blue blood" thing and the ritual of it all...very well done.</td>', 'Such elegance...that horse is gorgeous...I must admit I don''t like the idea of the fox hunt but I never seem to tire of looking at pictures of the scenes, I think it''s the whole "blue blood" thing and the ritual of it all...very well done.', '2005-11-07 10:51:11.000000', NULL, 1),
(1844508, 254215, 35804, '<td valign="top">FANTASTIC light...the tones are simply delicious...very nicely done.</td>', 'FANTASTIC light...the tones are simply delicious...very nicely done.', '2005-11-07 10:52:01.000000', NULL, 1),
(1844515, 253499, 35804, '<td valign="top">Oh my! What an excellent capture..and I must say quite a happy relief too, after looking at some rather horrid "suicide" type pictures...this just goes to show that not all "dead ends" need to be dark and disturbing...thank you for this image...I love it!</td>', 'Oh my! What an excellent capture..and I must say quite a happy relief too, after looking at some rather horrid "suicide" type pictures...this just goes to show that not all "dead ends" need to be dark and disturbing...thank you for this image...I love it!', '2005-11-07 10:58:01.000000', NULL, 1),
(1844516, 254342, 35804, '<td valign="top">Great slice o'' life image...those colors are fantastic!</td>', 'Great slice o'' life image...those colors are fantastic!', '2005-11-07 10:58:59.000000', NULL, 1),
(1844517, 252441, 35804, '<td valign="top">Interesting perspective...it has a really great abstract appeal...very nice.</td>', 'Interesting perspective...it has a really great abstract appeal...very nice.', '2005-11-07 11:00:36.000000', NULL, 1),
(1844519, 254176, 35804, '<td valign="top">...oh yes...the perfect title!</td>', '...oh yes...the perfect title!', '2005-11-07 11:02:47.000000', NULL, 1),
(1844522, 254560, 35804, '<td valign="top">A very unique take on the challenge! And you actually have made an image of a split end interesting to look at...well done!  : }</td>', 'A very unique take on the challenge! And you actually have made an image of a split end interesting to look at...well done!  : }', '2005-11-07 11:05:34.000000', NULL, 1),
(1844570, 254253, 35545, '<td valign="top">Love the colors and the mood.  It might have been better to crop it a little tighter.  It didn''t fit on my monitor, but that might be my monitor.</td>', 'Love the colors and the mood.  It might have been better to crop it a little tighter.  It didn''t fit on my monitor, but that might be my monitor.', '2005-11-07 11:38:41.000000', NULL, 1),
(1844571, 253784, 35545, '<td valign="top">Yes, this meets the challenge!  I wish the sky weren''t so blown out.</td>', 'Yes, this meets the challenge!  I wish the sky weren''t so blown out.', '2005-11-07 11:39:37.000000', NULL, 1),
(1844576, 253930, 35545, '<td valign="top">Oh, dear.  More of this post processing blur/glow and a lot of burning, I think.</td>', 'Oh, dear.  More of this post processing blur/glow and a lot of burning, I think.', '2005-11-07 11:41:24.000000', NULL, 1),
(1844619, 254518, 37719, '<td valign="top">One of the truly original shots in this challenge in my opinion.  Very well composed and shot.  Focus is spot on and colors are great.  PLacement of the subject is very nice as well.  I hope this ribbons!  Well done!</td>', 'One of the truly original shots in this challenge in my opinion.  Very well composed and shot.  Focus is spot on and colors are great.  PLacement of the subject is very nice as well.  I hope this ribbons!  Well done!', '2005-11-07 12:11:23.000000', NULL, 1),
(1844629, 253499, 32338, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2005-11-07 12:17:26.000000', NULL, 1),
(1844632, 254312, 32338, '<td valign="top">Perhaps a bit heavy on the post-processing but beautiful.</td>', 'Perhaps a bit heavy on the post-processing but beautiful.', '2005-11-07 12:18:36.000000', NULL, 1),
(1844634, 254195, 32338, '<td valign="top">Wow, that''s amazing.  One of the reasons I love DPC is the opportunity to see so many locations and ideas.</td>', 'Wow, that''s amazing.  One of the reasons I love DPC is the opportunity to see so many locations and ideas.', '2005-11-07 12:20:40.000000', NULL, 1),
(1844637, 254412, 32338, '<td valign="top">Strong image.</td>', 'Strong image.', '2005-11-07 12:20:56.000000', NULL, 1),
(1844639, 253497, 32338, '<td valign="top">Nice photo portraying a depressing theme.  The glass looks great.</td>', 'Nice photo portraying a depressing theme.  The glass looks great.', '2005-11-07 12:22:16.000000', NULL, 1),
(1844641, 254560, 32338, '<td valign="top">Unique</td>', 'Unique', '2005-11-07 12:23:18.000000', NULL, 1),
(1844642, 254176, 32338, '<td valign="top">Humorous</td>', 'Humorous', '2005-11-07 12:23:47.000000', NULL, 1),
(1844643, 253792, 32338, '<td valign="top">Colors are great!</td>', 'Colors are great!', '2005-11-07 12:24:09.000000', NULL, 1),
(1844645, 252554, 32338, '<td valign="top">Abstract</td>', 'Abstract', '2005-11-07 12:25:28.000000', NULL, 1),
(1844652, 254315, 33068, '<td valign="top">Something about this picture I just love.  Very emotive!  I keep coming back to it.    I''ll comment more later.  Nice job.</td>', 'Something about this picture I just love.  Very emotive!  I keep coming back to it.    I''ll comment more later.  Nice job.', '2005-11-07 12:29:23.000000', NULL, 1),
(1844655, 254205, 32338, '<td valign="top">For some reason this desperate theme has a touch of whimsy in it.  It seems too well laid out and planned or neat and arranged to convince me that this was a true end of life act.  Its a good photo - I''m just unsure of the mood that you were trying to portray.</td>', 'For some reason this desperate theme has a touch of whimsy in it.  It seems too well laid out and planned or neat and arranged to convince me that this was a true end of life act.  Its a good photo - I''m just unsure of the mood that you were trying to portray.', '2005-11-07 12:30:27.000000', NULL, 1),
(1844656, 254499, 32338, '<td valign="top">The tones and focus effectively create a desperate situation.</td>', 'The tones and focus effectively create a desperate situation.', '2005-11-07 12:31:15.000000', NULL, 1),
(1844659, 254264, 32338, '<td valign="top">Great tones.</td>', 'Great tones.', '2005-11-07 12:32:00.000000', NULL, 1),
