(1845291, 252727, 31399, '<td valign="top">very nice 10+</td>', 'very nice 10+', '2005-11-07 17:01:43.000000', NULL, 1),
(1845404, 253217, 24454, '<td valign="top">Very nice!  Soothing sky, and excellent color and sharpness.     I wonder what''s on the other side of that end of the road.   I see trees over there. . . I want to go there.</td>', 'Very nice!  Soothing sky, and excellent color and sharpness.     I wonder what''s on the other side of that end of the road.   I see trees over there. . . I want to go there.', '2005-11-07 18:05:06.000000', NULL, 1),
(1845409, 254013, 24454, '<td valign="top">That is REALLY awesome!     There are so many interesting things to look at.   The crashing waves, the stuff on the walk, the birds.   I really love this!</td>', 'That is REALLY awesome!     There are so many interesting things to look at.   The crashing waves, the stuff on the walk, the birds.   I really love this!', '2005-11-07 18:06:57.000000', NULL, 1),
