INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1845627, 252559, 6999, '<td valign="top">This is a really modern photograph. The saturation lends it something of the feel of a Martin Parr shot, as does the off-beat composition. I happen to see it, as I write, cropped on-screen below the blue wall-section, and wonder if tthat isn''t a stronger presentation of the scene - basically, i''m asking if the brightness of that blue hasn''t seduced your eye somewhat? Nevertheless, it''s certainly tthe strongest image i''ve seen in this challenge.<br/> <br/>Every element of frame has become important, which i like. There''s such strong and simple oranisation here, that even that collection of pipes becomes a fascinatingly different artefact. That process of making the ordinary extraordinary is one of good photography''s greatest strengths - and this re-inforcement of the idea that the simply observed moments of real life can outweigh in significance even the the most carefully set-up and processed pose. One could not produce this out of one''s imagination and a couple of willing models, and therefore it''s the stronger for it - and the more so at dpc. Lovely work</td>', 'This is a really modern photograph. The saturation lends it something of the feel of a Martin Parr shot, as does the off-beat composition. I happen to see it, as I write, cropped on-screen below the blue wall-section, and wonder if tthat isn''t a stronger presentation of the scene - basically, i''m asking if the brightness of that blue hasn''t seduced your eye somewhat? Nevertheless, it''s certainly tthe strongest image i''ve seen in this challenge. Every element of frame has become important, which i like. There''s such strong and simple oranisation here, that even that collection of pipes becomes a fascinatingly different artefact. That process of making the ordinary extraordinary is one of good photography''s greatest strengths - and this re-inforcement of the idea that the simply observed moments of real life can outweigh in significance even the the most carefully set-up and processed pose. One could not produce this out of one''s imagination and a couple of willing models, and therefore it''s the stronger for it - and the more so at dpc. Lovely work', '2005-11-07 19:22:36.000000', NULL, 1),
(1845628, 253800, 39664, '<td valign="top">Learn to punctuate!  Life''s (shows possession)<br/> <br/>This photo would make a nice anti-drug poster (if you fixed the title!)</td>', 'Learn to punctuate!  Life''s (shows possession) This photo would make a nice anti-drug poster (if you fixed the title!)', '2005-11-07 19:23:17.000000', NULL, 1),
(1845632, 254205, 39664, '<td valign="top">dark and gloomy.  This could be a poster for a suicide help/hotline.</td>', 'dark and gloomy.  This could be a poster for a suicide help/hotline.', '2005-11-07 19:24:29.000000', NULL, 1),
(1845633, 254528, 39664, '<td valign="top">OMG!  Did this boat really sink or did you creatively edit this?</td>', 'OMG!  Did this boat really sink or did you creatively edit this?', '2005-11-07 19:25:52.000000', NULL, 1),
(1845637, 254412, 39664, '<td valign="top">No, this looks like a portal to a wonderfully rustic ranch!</td>', 'No, this looks like a portal to a wonderfully rustic ranch!', '2005-11-07 19:26:53.000000', NULL, 1),
(1845638, 254562, 43565, '<td valign="top">This would be good if you had an ant or roach waling toward it.  As is, it really doesn''t hold my interest.</td>', 'This would be good if you had an ant or roach waling toward it.  As is, it really doesn''t hold my interest.', '2005-11-07 19:27:02.000000', NULL, 1),
(1845640, 254362, 39664, '<td valign="top">OK, I wonder if I am the only one noticing this but why are her boobs two different colors?</td>', 'OK, I wonder if I am the only one noticing this but why are her boobs two different colors?', '2005-11-07 19:28:00.000000', NULL, 1),
(1845643, 253569, 39664, '<td valign="top">Very pretty</td>', 'Very pretty', '2005-11-07 19:28:46.000000', NULL, 1),
(1845649, 254518, 39664, '<td valign="top">LOL!  The wicked witch is dead!</td>', 'LOL!  The wicked witch is dead!', '2005-11-07 19:30:32.000000', NULL, 1),
(1845653, 254283, 6999, '<td valign="top">In the same way I fail to understand people who think The Exorcist is the greatest film ever made, I fail to understand the near-obsession around here lately with this kind of mock-gothic type of stuff. I find it hard to believe that this has anything to do with the world in which any of us lives, and fail not least on those grounds to find anything very interesting in it. There is abundant and evident skill in this work - technical savvy, fine execution, mood, detail, off-beat but happy composition. but I wish that could be brought to a more grown-up ambition that these neo-baroque fantasies. I''m sorry, but it angers me to see such ability harnessed to such work.</td>', 'In the same way I fail to understand people who think The Exorcist is the greatest film ever made, I fail to understand the near-obsession around here lately with this kind of mock-gothic type of stuff. I find it hard to believe that this has anything to do with the world in which any of us lives, and fail not least on those grounds to find anything very interesting in it. There is abundant and evident skill in this work - technical savvy, fine execution, mood, detail, off-beat but happy composition. but I wish that could be brought to a more grown-up ambition that these neo-baroque fantasies. I''m sorry, but it angers me to see such ability harnessed to such work.', '2005-11-07 19:31:51.000000', NULL, 1),
(1845655, 253139, 39664, '<td valign="top">Except for the digital noise (haloing) along the tree tops and the edge of the dock, this is a lovely photo and nice comp!</td>', 'Except for the digital noise (haloing) along the tree tops and the edge of the dock, this is a lovely photo and nice comp!', '2005-11-07 19:31:56.000000', NULL, 1),
(1845657, 252651, 43565, '<td valign="top">Is that snow, or is it overexosed?  Can''t really see a street.  (The frame is too thcik IMO)</td>', 'Is that snow, or is it overexosed?  Can''t really see a street.  (The frame is too thcik IMO)', '2005-11-07 19:32:16.000000', NULL, 1),
(1845665, 254009, 39664, '<td valign="top">Pretty.  The yellows look a bit oversaturated.  This reminds me of the North Georgia Mountains.....Anna Ruby Falls.</td>', 'Pretty.  The yellows look a bit oversaturated.  This reminds me of the North Georgia Mountains.....Anna Ruby Falls.', '2005-11-07 19:34:38.000000', NULL, 1),
(1845666, 251665, 39664, '<td valign="top">Fierce!</td>', 'Fierce!', '2005-11-07 19:34:53.000000', NULL, 1),
