INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1847577, 253708, 29474, '<td valign="top">This image is very flat. There is nothing that jumps out and says ''look at me''.</td>', 'This image is very flat. There is nothing that jumps out and says ''look at me''.', '2005-11-08 14:26:30.000000', NULL, 1),
(1847579, 254531, 32644, '<td valign="top">Interesting but too dark. It fits the challenge though.</td>', 'Interesting but too dark. It fits the challenge though.', '2005-11-08 14:26:36.000000', NULL, 1),
(1847582, 254561, 29474, '<td valign="top">The technicals of this picture are all there. Sharpness in the right places, leading line, depth of field. But there is nor emotion ... nothing asking the question what is be aimed at.</td>', 'The technicals of this picture are all there. Sharpness in the right places, leading line, depth of field. But there is nor emotion ... nothing asking the question what is be aimed at.', '2005-11-08 14:28:42.000000', NULL, 1),
(1847583, 252553, 208, '<td valign="top">I think this picture says the opposite of "dead end": the road seems to keep going in both directions. Having said that, the framing is great: the road seems to keep going in both directions. It wraps neatly around the picture, leading straight into the fall colors. I like the colors and using the tree on the right.</td>', 'I think this picture says the opposite of "dead end": the road seems to keep going in both directions. Having said that, the framing is great: the road seems to keep going in both directions. It wraps neatly around the picture, leading straight into the fall colors. I like the colors and using the tree on the right.', '2005-11-08 14:29:06.000000', NULL, 1),
(1847584, 254129, 32644, '<td valign="top">I like this place but your shot seems to have been post processed a little too much. The water looks like mud - is it? I would like to see the original.</td>', 'I like this place but your shot seems to have been post processed a little too much. The water looks like mud - is it? I would like to see the original.', '2005-11-08 14:29:16.000000', NULL, 1),
(1847590, 254563, 208, '<td valign="top">I almost like the lighting: I think the center barrell is too bright. The light in the sky and the angle of the sign want me to focus on the person in silhouette, but the barrell keeps screaming for attention.</td>', 'I almost like the lighting: I think the center barrell is too bright. The light in the sky and the angle of the sign want me to focus on the person in silhouette, but the barrell keeps screaming for attention.', '2005-11-08 14:31:27.000000', NULL, 1),
(1847604, 253256, 208, '<td valign="top">It''s interesting how all those orange leaves make me look at the blue sky.</td>', 'It''s interesting how all those orange leaves make me look at the blue sky.', '2005-11-08 14:34:13.000000', NULL, 1),
(1847613, 254077, 208, '<td valign="top">Cool idea, but it seems slighting out of focus.</td>', 'Cool idea, but it seems slighting out of focus.', '2005-11-08 14:36:16.000000', NULL, 1),
(1847764, 253625, 10263, '<td valign="top">Very emotional image. Well done</td>', 'Very emotional image. Well done', '2005-11-08 15:54:26.000000', NULL, 1),
