INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1849355, 253775, 10263, '<td valign="top">I hate the topic but it is indeed a dead end. I don''t think the subject should have been looking at the camera. It looks too posed this way.</td>', 'I hate the topic but it is indeed a dead end. I don''t think the subject should have been looking at the camera. It looks too posed this way.', '2005-11-09 01:14:54.000000', NULL, 1),
(1849364, 254237, 10263, '<td valign="top">I like the old town down house. The grass looks freshly mowed though which makes it look unreal. The color of the lawn looks a bit fake. With all the dried brown grass around it, it looks as though someone was watering this lawn but for what purpose. The composition is good.</td>', 'I like the old town down house. The grass looks freshly mowed though which makes it look unreal. The color of the lawn looks a bit fake. With all the dried brown grass around it, it looks as though someone was watering this lawn but for what purpose. The composition is good.', '2005-11-09 01:20:30.000000', NULL, 1),
(1849367, 254068, 10263, '<td valign="top">Definately a dead end. I like the blue tones. Not fond of the border.</td>', 'Definately a dead end. I like the blue tones. Not fond of the border.', '2005-11-09 01:22:02.000000', NULL, 1),
(1849375, 254521, 10263, '<td valign="top">I like this. Makes me dizzy looking up at the buildings. Holds my interest and keeps me looking at more details. Fits the challenge nicely</td>', 'I like this. Makes me dizzy looking up at the buildings. Holds my interest and keeps me looking at more details. Fits the challenge nicely', '2005-11-09 01:24:13.000000', NULL, 1),
(1849544, 253780, 47592, '<td valign="top">Conveys the mood very well.<br/>Technically imperfect, but not unpleasantly so.<br/>Good work.</td>', 'Conveys the mood very well.Technically imperfect, but not unpleasantly so.Good work.', '2005-11-09 03:16:29.000000', NULL, 1),
(1849634, 253272, 36132, '<td valign="top">I like this picture, the colour is brillant and the point is well made here i think. Good luck!</td>', 'I like this picture, the colour is brillant and the point is well made here i think. Good luck!', '2005-11-09 04:21:45.000000', NULL, 1),
(1849660, 253223, 16046, '<td valign="top">I thought of something like this, just couldn''t carry it out, good idea.</td>', 'I thought of something like this, just couldn''t carry it out, good idea.', '2005-11-09 04:38:42.000000', NULL, 1),
(1850079, 254068, 21816, '<td valign="top">I find the thick border on this a little over powering but otherwise an outstanding photo!</td>', 'I find the thick border on this a little over powering but otherwise an outstanding photo!', '2005-11-09 08:59:52.000000', NULL, 1),
(1850087, 254042, 21816, '<td valign="top">I hope Elvis had left the hospital! Well timed shot!</td>', 'I hope Elvis had left the hospital! Well timed shot!', '2005-11-09 09:02:42.000000', NULL, 1),
(1850090, 253294, 21816, '<td valign="top">Wow!</td>', 'Wow!', '2005-11-09 09:03:33.000000', NULL, 1),
(1850170, 253797, 40386, '<td valign="top">This would have been far better if you had increased the contrast a bit to bring out the colors more.</td>', 'This would have been far better if you had increased the contrast a bit to bring out the colors more.', '2005-11-09 09:40:46.000000', NULL, 1),
(1850183, 252668, 40386, '<td valign="top">I personally dont like the soft (Neat Image?) effect on this shot, would have been great with a tad more contrast and sharper except for the water.  Maybe if you had taken a few steps to your right and lost some of the dark trees too?</td>', 'I personally dont like the soft (Neat Image?) effect on this shot, would have been great with a tad more contrast and sharper except for the water.  Maybe if you had taken a few steps to your right and lost some of the dark trees too?', '2005-11-09 09:43:30.000000', NULL, 1),
(1850203, 253708, 40386, '<td valign="top">This shot would have been better if it had more contrast and you had adjusted the color as it has a distinct Cyan cast.</td>', 'This shot would have been better if it had more contrast and you had adjusted the color as it has a distinct Cyan cast.', '2005-11-09 09:47:50.000000', NULL, 1),
(1850225, 254129, 40386, '<td valign="top">I am not sure if I like the "graduated" effect on this image and cant make up my mind if it is an actual filter or the way the light actually was (Graduated Tobacco filter maybe?) as it leaves the sign looking a bit dark.  Also it has the Neat Image sort of effect which has left the writing on the sign looking strange.</td>', 'I am not sure if I like the "graduated" effect on this image and cant make up my mind if it is an actual filter or the way the light actually was (Graduated Tobacco filter maybe?) as it leaves the sign looking a bit dark.  Also it has the Neat Image sort of effect which has left the writing on the sign looking strange.', '2005-11-09 09:51:32.000000', NULL, 1),
