(1857667, 252727, 34192, '<td valign="top">My only 10.  Kind of thrown by the vertical placement.  Maybe the point.  Love the way you put this together - think this image goes way beyond DPC.  I can''t see it not winning unless you get hit by the DNMC challenge police.  Beautiful textures and coloration.  What else can I say - you know you''ve done it with this one.  :)</td>', 'My only 10.  Kind of thrown by the vertical placement.  Maybe the point.  Love the way you put this together - think this image goes way beyond DPC.  I can''t see it not winning unless you get hit by the DNMC challenge police.  Beautiful textures and coloration.  What else can I say - you know you''ve done it with this one.  :)', '2005-11-11 08:23:51.000000', NULL, 1),
(1857735, 254033, 47747, '<td valign="top">One of the best here !</td>', 'One of the best here !', '2005-11-11 09:13:10.000000', NULL, 1),
