(1857892, 254482, 208, '<td valign="top">I''m going to pretend the red-eye is on purpose, but the people should be in focus, not the the background</td>', 'I''m going to pretend the red-eye is on purpose, but the people should be in focus, not the the background', '2005-11-11 11:11:27.000000', NULL, 1),
(1857897, 253497, 208, '<td valign="top">If you''re making the point that alcohol(ism) is a dead end, this isn''t the picture to do it. It''s very classy - I really want some Scotch right now. I like the arrangement and lighting; the half-glass is a nice touch.</td>', 'If you''re making the point that alcohol(ism) is a dead end, this isn''t the picture to do it. It''s very classy - I really want some Scotch right now. I like the arrangement and lighting; the half-glass is a nice touch.', '2005-11-11 11:14:59.000000', NULL, 1);
