(1860448, 254362, 17203, '<td valign="top"><b>Brilliant</b> concept, perfectly lit and executed. One of my favorites, and sure to make the top 5.</td>', 'Brilliant concept, perfectly lit and executed. One of my favorites, and sure to make the top 5.', '2005-11-12 12:46:38.000000', NULL, 1),
(1860455, 253664, 39483, '<td valign="top">IMHO, it almost seems like adding more grain would add even more impact!<br/> I like the concept and the composition works well save for just the bit of her head that breaks the horizon.</td>', 'IMHO, it almost seems like adding more grain would add even more impact! I like the concept and the composition works well save for just the bit of her head that breaks the horizon.', '2005-11-12 12:47:57.000000', NULL, 1),
(1860470, 254139, 39483, '<td valign="top">good concept and well composed! The photo does seem a bit too smooth, it''s hard getting the feel of the cheese and wood textures. Nice low angle by the way!</td>', 'good concept and well composed! The photo does seem a bit too smooth, it''s hard getting the feel of the cheese and wood textures. Nice low angle by the way!', '2005-11-12 12:50:33.000000', NULL, 1),
(1860476, 253499, 17203, '<td valign="top">Nails the topic. Color, lighting, DOF and focus are all right where they should be, and you''ve made it special by capturing the "moment" of takeoff. I''d probably crop a little more off the top and bottom, but what would REALLY improve this shot is a ribbon next to the title. ;-)  10</td>', 'Nails the topic. Color, lighting, DOF and focus are all right where they should be, and you''ve made it special by capturing the "moment" of takeoff. I''d probably crop a little more off the top and bottom, but what would REALLY improve this shot is a ribbon next to the title. ;-)  10', '2005-11-12 12:52:13.000000', NULL, 1),
(1860477, 254562, 39483, '<td valign="top">It''s a good concept and it''s well shot, focus and exposure wise! I might have been tempted to add two ''fake'' antenneas sticking out of the right corner of the photo to add more impact :)</td>', 'It''s a good concept and it''s well shot, focus and exposure wise! I might have been tempted to add two ''fake'' antenneas sticking out of the right corner of the photo to add more impact :)', '2005-11-12 12:52:20.000000', NULL, 1),
(1860483, 254144, 17203, '<td valign="top">This defies every principle we hold dear... it''s grainy, the subject is unappealing, the scene is kinda'' cluttered... and it''s <i>beautiful.</i> A wonderful example of artistic photography that draws you in with an elegant composition and a "peaceful'' ending. I particularly like that the mouse seems to be holding the leaf like a flower, and the title is almost poetic. One of the best in this challenge IMO. Great job!<br/> <br/>EDIT- it appears that I made a scoring error and gave this something less than a 10 on the first pass. I''ve corrected the problem. ;-)</td>', 'This defies every principle we hold dear... it''s grainy, the subject is unappealing, the scene is kinda'' cluttered... and it''s beautiful. A wonderful example of artistic photography that draws you in with an elegant composition and a "peaceful'' ending. I particularly like that the mouse seems to be holding the leaf like a flower, and the title is almost poetic. One of the best in this challenge IMO. Great job! EDIT- it appears that I made a scoring error and gave this something less than a 10 on the first pass. I''ve corrected the problem. ;-)', '2005-11-12 12:54:23.000000', NULL, 1),
(1860486, 252553, 39483, '<td valign="top">It''s actually a very nice angle and you really get the feel of the sinuous road! IMHO, more luminosity and a less soft focus would help a bit...</td>', 'It''s actually a very nice angle and you really get the feel of the sinuous road! IMHO, more luminosity and a less soft focus would help a bit...', '2005-11-12 12:55:02.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1860493, 254417, 39483, '<td valign="top">Of all the cemetary shots in this challenge, I like this one best. The colors are amazing! IMHO, a bit more contrast at the bottom of the photo would help bring out the front toombstones away from the dark leaves. Maybe a bit of dodging and burning? not sure...</td>', 'Of all the cemetary shots in this challenge, I like this one best. The colors are amazing! IMHO, a bit more contrast at the bottom of the photo would help bring out the front toombstones away from the dark leaves. Maybe a bit of dodging and burning? not sure...', '2005-11-12 12:57:30.000000', NULL, 1),
(1860499, 253139, 39483, '<td valign="top">I like how the angle has the view over the water and off the pier, it creates motion in the image by having the viewer feel like he/she is falling... The sky does seem a bit oversaturated and in places overexposed...</td>', 'I like how the angle has the view over the water and off the pier, it creates motion in the image by having the viewer feel like he/she is falling... The sky does seem a bit oversaturated and in places overexposed...', '2005-11-12 12:59:48.000000', NULL, 1),
(1860507, 254486, 42638, '<td valign="top">Interesting interpretation, dead end of a game. Very clear and focus.</td>', 'Interesting interpretation, dead end of a game. Very clear and focus.', '2005-11-12 13:08:36.000000', NULL, 1),
(1860508, 254422, 42638, '<td valign="top">Interesting picture. Love the blue sky and the single tall palm tree.</td>', 'Interesting picture. Love the blue sky and the single tall palm tree.', '2005-11-12 13:09:15.000000', NULL, 1),
(1860511, 254518, 42567, '<td valign="top">this is so funny..!!  Good job!</td>', 'this is so funny..!!  Good job!', '2005-11-12 13:09:54.000000', NULL, 1),
(1860512, 254481, 42638, '<td valign="top">Interesting picture. The B&amp;W give it power, very nice</td>', 'Interesting picture. The B&W give it power, very nice', '2005-11-12 13:09:54.000000', NULL, 1),
(1860513, 254129, 42638, '<td valign="top">Nice picture, love the colors but it makes the sign a bit hard to read.</td>', 'Nice picture, love the colors but it makes the sign a bit hard to read.', '2005-11-12 13:10:42.000000', NULL, 1),
(1860514, 253354, 42638, '<td valign="top">Wow, interesting picture. Looks very gloomy and dead, Nice!</td>', 'Wow, interesting picture. Looks very gloomy and dead, Nice!', '2005-11-12 13:11:17.000000', NULL, 1),
(1860518, 253886, 42638, '<td valign="top">Very nice picture. Love the title, definate fit. The picture is a bit small so its hard to see more of the details.</td>', 'Very nice picture. Love the title, definate fit. The picture is a bit small so its hard to see more of the details.', '2005-11-12 13:15:15.000000', NULL, 1),
(1860533, 254411, 42638, '<td valign="top">Very nice interpretation. Love the cityscape through the haze. The Yellow of the sign really stands out.</td>', 'Very nice interpretation. Love the cityscape through the haze. The Yellow of the sign really stands out.', '2005-11-12 13:25:17.000000', NULL, 1),
(1860575, 253072, 43487, '<td valign="top">what a loser who is in this dumb pic??!? lol j/k bud got to love seeing yourself in a pic and lookin dag on good i tell ya man o man im hot!!</td>', 'what a loser who is in this dumb pic??!? lol j/k bud got to love seeing yourself in a pic and lookin dag on good i tell ya man o man im hot!!', '2005-11-12 13:54:25.000000', NULL, 1),
(1860615, 254417, 10263, '<td valign="top">Double dead ends :) The colors are wonderful. I like the shadows from the tombstones. I think I would have liked it better without the shadowed area on the bottom. When I cover most of the darker area at the bottom, the tombstones pop out more. Try it and see what ya think. Good job :)</td>', 'Double dead ends :) The colors are wonderful. I like the shadows from the tombstones. I think I would have liked it better without the shadowed area on the bottom. When I cover most of the darker area at the bottom, the tombstones pop out more. Try it and see what ya think. Good job :)', '2005-11-12 14:18:53.000000', NULL, 1),
(1860630, 254042, 10263, '<td valign="top">This is an exciting photo. Great capture. I''m glad you left the crowd in. Makes a greater impact. Also the green lights and the balloons on the left help the composition. The only thing I think might make it better is having less sky on the top. When I cover the top except just above the top balloon, it has an even greater impact for me.</td>', 'This is an exciting photo. Great capture. I''m glad you left the crowd in. Makes a greater impact. Also the green lights and the balloons on the left help the composition. The only thing I think might make it better is having less sky on the top. When I cover the top except just above the top balloon, it has an even greater impact for me.', '2005-11-12 14:25:34.000000', NULL, 1),
(1860651, 254482, 10263, '<td valign="top">This one didn''t score well for me for the following reasons. 1. The focus is off.  2. The woman has red eyes. 3. I don''t like the composition with it cut off above her knees and too much space above their heads. I do see how it fits the challenge however. He indeed looks like he met a dead end :) Keep entering challenges. I''m sure you will improve.</td>', 'This one didn''t score well for me for the following reasons. 1. The focus is off.  2. The woman has red eyes. 3. I don''t like the composition with it cut off above her knees and too much space above their heads. I do see how it fits the challenge however. He indeed looks like he met a dead end :) Keep entering challenges. I''m sure you will improve.', '2005-11-12 14:33:44.000000', NULL, 1),
(1860670, 254362, 39057, '<td valign="top">I love this shot and the girl!   8</td>', 'I love this shot and the girl!   8', '2005-11-12 14:45:13.000000', NULL, 1),
(1860673, 253782, 10263, '<td valign="top">This is scary. To me it would have seemed more of a dead end without the light areas on the right. Looks like the girls could run through the water up to whatever those windows lead to. Or maybe leave the water but get rid of the windows. An angle without showing the fence would be better for me too. I like their expressions and that the older girl is trying to protect the younger one. I like the post processing too. (I gotta learn to do that) Oh, and the lower part of the mans pants seem a little bright for the rest of the photo. <br/> <br/>Definately holds my attention and keeps me looking for other things I might have missed. It also makes me want to finish the story. Either with an AK47 or learning that man is actually a kind stranger who delivers them safely home.  :)</td>', 'This is scary. To me it would have seemed more of a dead end without the light areas on the right. Looks like the girls could run through the water up to whatever those windows lead to. Or maybe leave the water but get rid of the windows. An angle without showing the fence would be better for me too. I like their expressions and that the older girl is trying to protect the younger one. I like the post processing too. (I gotta learn to do that) Oh, and the lower part of the mans pants seem a little bright for the rest of the photo.  Definately holds my attention and keeps me looking for other things I might have missed. It also makes me want to finish the story. Either with an AK47 or learning that man is actually a kind stranger who delivers them safely home.  :)', '2005-11-12 14:47:53.000000', NULL, 1),
(1860805, 254060, 208, '<td valign="top">I like the fairytale feel of this.</td>', 'I like the fairytale feel of this.', '2005-11-12 16:19:13.000000', NULL, 1),
(1860808, 254155, 208, '<td valign="top">I''d like to see more red in the wine''s shadow.</td>', 'I''d like to see more red in the wine''s shadow.', '2005-11-12 16:21:19.000000', NULL, 1),
(1860811, 254374, 208, '<td valign="top">Looks like post-processing did something weird to the gray cloud in the middle. But the tree on the right looks great.</td>', 'Looks like post-processing did something weird to the gray cloud in the middle. But the tree on the right looks great.', '2005-11-12 16:23:49.000000', NULL, 1),
(1860812, 252293, 11800, '<td valign="top">no they don''t. The abuse of drugs may kill but there are addicts that have lived long and useful lives. But on the other hand, we have all those prescriptions that Doctors give us to make us better. Surely they wouldn''t be giving them to us if they thought they always lead to a dead end. The title, imo, is a false statement.</td>', 'no they don''t. The abuse of drugs may kill but there are addicts that have lived long and useful lives. But on the other hand, we have all those prescriptions that Doctors give us to make us better. Surely they wouldn''t be giving them to us if they thought they always lead to a dead end. The title, imo, is a false statement.', '2005-11-12 16:24:01.000000', NULL, 1),
(1860816, 253833, 208, '<td valign="top">Having a person in the darkness is a nice touch. Kinda creepy. I like the shadows and framing, too.</td>', 'Having a person in the darkness is a nice touch. Kinda creepy. I like the shadows and framing, too.', '2005-11-12 16:27:23.000000', NULL, 1),
(1860820, 252554, 208, '<td valign="top">Cool idea, but I don''t like the pixelation. I think if it were smoother, this would be better.</td>', 'Cool idea, but I don''t like the pixelation. I think if it were smoother, this would be better.', '2005-11-12 16:29:37.000000', NULL, 1),
(1860822, 254160, 11800, '<td valign="top">This is simple and not overdramatic. Very tastefully done. I keep looking at all the stuff and thinking it''s real. I hope not. but that''s why I gave it a 9</td>', 'This is simple and not overdramatic. Very tastefully done. I keep looking at all the stuff and thinking it''s real. I hope not. but that''s why I gave it a 9', '2005-11-12 16:30:43.000000', NULL, 1),
